SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0950000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 95, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "95", "printedPageNumber": 95, "pdfPageNumber": 478, "sequenceIndex": 85, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0950100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REQUISITES OF GOOD SALAAT SUGGESTED BY SOOFIA", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0950000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There are some who shall remain in ruku and some in sajdah till eternity. Allah has combined all these postures of the Angels in our salaat, so that we may get our shares from each type of their worship. Recitation of the Qur''an in salaat is an addition over and above their worship. While salaat is the sum total of all the postures in the Angels'' methods of worship, it gives out its best when it is offered by a person possessing angelic habits. That is why the Prophet (Sallallaho alaihe wasallam) says, \"For (a good) salaat, keep your back and stomach light.\" The back of a person is said to be light when he has very few worldly encumbrances, and his stomach is light when he eats moderately to avoid indolence and laziness, which is a sure outcome of gluttony.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950200-0000-4000-8000-000000000001", "structuralNodeId": "b0950100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REQUISITES OF GOOD SALAAT SUGGESTED BY SOOFIA", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950300-0000-4000-8000-000000000001", "structuralNodeId": "b0950100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Soofia write: \"There are twelve thousand virtues in salaat, which can be achieved through twelve points. If a person is to acquire full benefit from salaat, then, he must take care of these points. Sincerity is of course essential at every step. These points are as follows:\n\n1. Knowledge: An action performed without knowledge is far inferior to the one done with full knowledge about it. We should therefore know:\n(a) Which of the Islamic Practices are fardh and which are sunnat.\n(b) What is fardh and what is sunnat in wudhu and salaat.\n(c) How does Satan cause obstruction in the proper observance of salaat.\n\n2. Wudhu: We must try to:\n(a) Clean our heart of jealousy and malice, just as we wash the other parts of our body.\n(b) Keep ourselves clean of sins.\n(c) Be neither wasteful nor abstemious in the use of water.\n\n3. Dress: It should be:\n(a) Got through honest living.\n(b) Clean.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}]}'::jsonb);